28	
29	    public void service(@Val Owner owner, @Val Boolean sharesHousehold,
30	            OwnerRepository ownerRepository) {
31	        owner.setHouseholdSize(1); // a household of one until an existing member is found
32	        if (!Boolean.TRUE.equals(sharesHousehold)) {
33	            return; // did not opt in: never joins an existing household
34	        }
35	        String lastName = key(owner.getLastName());
36	        String address = AddressNormalizer.normalize(owner.getAddress());
37	        List<Owner> household = new ArrayList<>();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
40	                continue; // same record (e.g. re-save)
41	            }
42	            if (lastName.equals(key(existing.getLastName()))
43	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
44	                household.add(existing);
45	            }
46	        }
47	        if (household.isEmpty()) {
48	            return; // no existing owner at this last name + address
49	        }
50	        // Assign the same stable household identifier to all members, and record the household's
51	        // size (existing members plus this new owner) on every member so it reflects the
52	        // household as it stands after this create.
53	        String householdId = householdId(lastName, address, household);
54	        int householdSize = household.size() + 1;
55	        owner.setHouseholdId(householdId);
56	        owner.setHouseholdSize(householdSize);
57	        for (Owner member : household) {
58	            member.setHouseholdId(householdId);
59	            member.setHouseholdSize(householdSize);
60	            ownerRepository.save(member);
61	        }
62	    }
63	
64	    /**
65	     * The household's stable shared identifier: reuse the id an existing member already carries
66	     * (so a household keeps one value over time); otherwise derive it deterministically from the
67	     * normalized last name and address, so independent joiners compute the same value.
68	     */
